styles:
body { margin: 0; }
    a { color: #6b521f; text-decoration: underline; text-decoration-color: rgba(138,109,59,0.35); }
    a:hover { color: #5c4826; }
    ::selection { background: rgba(138,109,59,0.25); }

logic:
class Component extends DCLogic {
  state = {
    zoomIndex: null,
    scale: 1,
    offsetX: 0,
    offsetY: 0,
    dragging: false,
    dragStartX: 0,
    dragStartY: 0,
    dragOffsetStartX: 0,
    dragOffsetStartY: 0
  };

  noteData = [
    {
      key: "1964-bolivar",
      label: "Cincuenta Pesos Oro \u00b7 1 de enero de 1964 \u00b7 Serie Z",
      denomination: "Cincuenta Pesos Oro",
      date: "1 de enero de 1964 (Serie Z)",
      obverse: "Rojo carmín sobre fondo grabado. Óvalo con el retrato de Simón Bolívar en uniforme militar a la izquierda. Gran cifra ornamental \u201c50\u201d al centro con sobreimpresión roja \u201cSPECIMEN\u201d. Numeración en ceros (00000) y firmas de Gerente y Secretario canceladas por perforaciones.",
      reverse: "Verde oliva. Óvalo central con un busto alegórico femenino de Colombia, flanqueado por grandes cifras \u201c50\u201d y guilloches simétricos.",
      condition: "Espécimen sin circular, con perforaciones de cancelación características y numeración en ceros.",
      rarity: "Ejemplar clásico de mediados de siglo, con la sobreimpresión inglesa \u201cSPECIMEN\u201d propia de la producción ABNC de la época.",
      catalogRef: "Pick #407 (tipo, serie 1960\u20131970)",
      description: "Espécimen clásico de mediados de los años 1960, con el retrato del Libertador Simón Bolívar y la sobreimpresión en inglés \u201cSPECIMEN\u201d propia de la producción de American Bank Note Company para la banca centralizada colombiana de la época.",
      jpg: "uploads/colombia-banco-de-la-republica-50-pesos-oro-1964-specimen.jpg",
      webp: "uploads/colombia-banco-de-la-republica-50-pesos-oro-1964-specimen.webp",
      webp640: "uploads/colombia-banco-de-la-republica-50-pesos-oro-1964-specimen-640.webp",
      alt: "Billete especimen de Cincuenta Pesos Oro de El Banco de la República, Colombia, fechado 1 de enero de 1964, anverso con el retrato de Simón Bolívar y reverso con un busto alegórico de Colombia"
    },
    {
      key: "1985-camilo-torres",
      label: "Cincuenta Pesos Oro \u00b7 1 de enero de 1985",
      denomination: "Cincuenta Pesos Oro",
      date: "1 de enero de 1985",
      obverse: "Multicolor (negro, verde y naranja). Retrato de Camilo Torres (sacerdote, intelectual y prócer de la independencia) a la derecha. Leyenda: \u201cEL BANCO DE LA REPÚBLICA \u00b7 PAGARÁ AL PORTADOR CINCUENTA PESOS ORO \u00b7 BOGOTÁ, 1 DE ENERO DE 1985\u201d. Sobreimpresión roja \u201cMUESTRA\u201d. Numeración en ceros (000000000). Firmas de Gerente y Abogado Subgerente canceladas por perforaciones.",
      reverse: "Multicolor. Orquídea Cattleya amarilla (flor nacional) al centro, junto con el escudo de Colombia y elementos arquitectónicos. Texto: \u201cCINCUENTA PESOS ORO\u201d y \u201cORQUÍDEAS DE COLOMBIA\u201d. Sobreimpresión roja \u201cMUESTRA SIN VALOR\u201d.",
      condition: "Gema sin circular, con perforaciones de cancelación características (punch holes) y numeración en ceros. Color y detalle sobresalientes.",
      rarity: "Espécimen atractivo de emisión tardía que destaca la flora y la historia colombianas.",
      catalogRef: "Pick #425 (tipo, serie 1984\u20131986)",
      description: "Espécimen de la serie renovada de los años 1980, con el retrato de Camilo Torres y orquídeas colombianas en el reverso. La sobreimpresión castellana \u201cMUESTRA SIN VALOR\u201d refleja la nacionalización editorial de la moneda colombiana en esta etapa tardía del siglo XX.",
      jpg: "uploads/colombia-banco-de-la-republica-50-pesos-oro-1985-specimen.jpg",
      webp: "uploads/colombia-banco-de-la-republica-50-pesos-oro-1985-specimen.webp",
      webp640: "uploads/colombia-banco-de-la-republica-50-pesos-oro-1985-specimen-640.webp",
      alt: "Billete especimen de Cincuenta Pesos Oro de El Banco de la República, Colombia, fechado 1 de enero de 1985, anverso con el retrato de Camilo Torres y reverso con orquídeas colombianas"
    }
  ];

  focusClose = () => {
    const closeBtn = document.querySelector('[data-zoom-close]');
    if (closeBtn) { closeBtn.focus(); return; }
    requestAnimationFrame(this.focusClose);
  };

  openZoomAt = (index) => {
    this.setState({ zoomIndex: index, scale: 1, offsetX: 0, offsetY: 0 });
    requestAnimationFrame(() => requestAnimationFrame(this.focusClose));
  };

  closeZoom = () => {
    this.setState({ zoomIndex: null });
  };

  stopPropagation = (e) => e.stopPropagation();

  zoomIn = () => {
    this.setState(s => ({ scale: Math.min(4, Math.round((s.scale + 0.5) * 10) / 10) }));
  };

  zoomOut = () => {
    this.setState(s => {
      const next = Math.max(1, Math.round((s.scale - 0.5) * 10) / 10);
      return { scale: next, offsetX: next === 1 ? 0 : s.offsetX, offsetY: next === 1 ? 0 : s.offsetY };
    });
  };

  onWheel = (e) => {
    e.preventDefault();
    const delta = e.deltaY > 0 ? -0.25 : 0.25;
    this.setState(s => {
      const next = Math.min(4, Math.max(1, Math.round((s.scale + delta) * 100) / 100));
      return { scale: next, offsetX: next === 1 ? 0 : s.offsetX, offsetY: next === 1 ? 0 : s.offsetY };
    });
  };

  onPointerDown = (e) => {
    if (this.state.scale <= 1) return;
    this.setState({
      dragging: true,
      dragStartX: e.clientX,
      dragStartY: e.clientY,
      dragOffsetStartX: this.state.offsetX,
      dragOffsetStartY: this.state.offsetY
    });
  };

  onPointerMove = (e) => {
    if (!this.state.dragging) return;
    const dx = e.clientX - this.state.dragStartX;
    const dy = e.clientY - this.state.dragStartY;
    this.setState({ offsetX: this.state.dragOffsetStartX + dx, offsetY: this.state.dragOffsetStartY + dy });
  };

  onPointerUp = () => this.setState({ dragging: false });

  onKeyDown = (e) => {
    if (e.key === "Escape" && this.state.zoomIndex !== null) this.closeZoom();
  };

  componentDidMount() {
    document.addEventListener("keydown", this.onKeyDown);
    if (typeof document !== "undefined" && document.documentElement) {
      document.documentElement.lang = "es";
    }
  }

  componentWillUnmount() {
    document.removeEventListener("keydown", this.onKeyDown);
  }

  renderVals() {
    const s = this.state;
    const notes = this.noteData.map((n, i) => Object.assign({}, n, { openZoom: () => this.openZoomAt(i) }));
    const active = s.zoomIndex !== null ? this.noteData[s.zoomIndex] : null;

    return {
      notes,
      zoomIndex: s.zoomIndex !== null,
      closeZoom: this.closeZoom,
      stopPropagation: this.stopPropagation,
      zoomInHandler: this.zoomIn,
      zoomOutHandler: this.zoomOut,
      onWheel: this.onWheel,
      onPointerDown: this.onPointerDown,
      onPointerMove: this.onPointerMove,
      onPointerUp: this.onPointerUp,
      zoomInDisabled: s.scale >= 4,
      zoomOutDisabled: s.scale <= 1,
      zoomPercent: Math.round(s.scale * 100) + "%",
      imgTransform: `translate(${s.offsetX}px, ${s.offsetY}px) scale(${s.scale})`,
      imgCursor: s.scale > 1 ? (s.dragging ? "grabbing" : "grab") : "default",
      activeNoteJpg: active ? active.jpg : "",
      activeNoteWebp: active ? active.webp : ""
    };
  }
}
